<?php

namespace App\Support;

use Illuminate\Support\Facades\File;

/**
 * Above-the-fold CSS inlined into the homepage <head>, generated by
 * `php artisan rgu:build-css`.
 *
 * Like the stylesheets it is cut from, the file points at images with
 * url("../storage/..."), relative to public/css. Inlined into the page those
 * must become full storage URLs.
 */
class CriticalCss
{
    public const PATH = 'css/critical.css';

    public function inline(): string
    {
        $path = public_path(self::PATH);
        $css = File::exists($path) ? File::get($path) : '';

        return preg_replace(
            '#url\((["\']?)\.\./storage/#i',
            'url($1'.asset('storage').'/',
            $css
        );
    }
}
